CREATE TABLE uploads (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, state TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>0), checksum TEXT NOT NULL, content_type TEXT NOT NULL, storage_key TEXT NOT NULL, multipart_upload_id TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE upload_parts (upload_id TEXT NOT NULL, part_number INTEGER NOT NULL CHECK(part_number BETWEEN 1 AND 10000), etag TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>0), PRIMARY KEY(upload_id,part_number));
CREATE TABLE shares (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, upload_id TEXT NOT NULL, title TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('public','unlisted','private')), revoked INTEGER DEFAULT 0 CHECK(revoked IN (0,1)), expires_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE share_members (share_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL, PRIMARY KEY (share_id,user_id));
CREATE TABLE share_comments (id TEXT PRIMARY KEY, share_id TEXT NOT NULL, author_id TEXT NOT NULL, author_name TEXT NOT NULL, timestamp_ms INTEGER NOT NULL CHECK(timestamp_ms>=0), body TEXT NOT NULL, resolved INTEGER DEFAULT 0 CHECK(resolved IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_shares_owner ON shares(owner_id); CREATE INDEX idx_comments_share ON share_comments(share_id);
